  function uxListingCard(x,index){
    var saved=Array.isArray(state.saved)&&state.saved.some(function(n){return n&&n.kind==='listing'&&listingSavedKey(n)===listingSavedKey(x)});
    var duplicate=x.duplicateCount>1?'<span class="intelUxBadge duplicate">'+uxIcon('repeat')+' Có thể tin đăng lại · '+escIntel(x.duplicateCount)+' bản ghi</span>':'';
    var freshness=listingFreshnessLabel(x),freshClass=listingFreshness(x);
    var facts=[];
    if(x.areaM2!=null)facts.push('<span><b>'+escIntel(areaLabel(x.areaM2))+'</b><small>Diện tích</small></span>');
    if(x.pricePerM2!=null)facts.push('<span><b>'+escIntel(m2Label(x.pricePerM2))+'</b><small>Giá/m²</small></span>');
    if(x.hasCertificate)facts.push('<span><b>Có dấu hiệu sổ</b><small>Đọc từ nội dung tin</small></span>');
    var summary=text(x.summary||'').trim();if(summary.length>220)summary=summary.slice(0,220).replace(/\s+\S*$/,'')+'…';
    var meta=[],areaText=listingAreaLabel(x);if(areaText)meta.push(areaText);if(x.publishedAt)meta.push('Đăng '+shortDate(x.publishedAt));
    return '<article class="intelUxListingCard"><div class="intelUxCardTop"><span class="intelUxBadge '+freshClass+'">'+escIntel(freshness)+'</span>'+duplicate+'</div><div class="intelUxListingSource">'+escIntel(x.portalName||'Nguồn rao')+'</div><h3>'+escIntel(x.title)+'</h3><div class="intelUxListingMeta">'+(meta.length?escIntel(meta.join(' · ')):'Ngày đăng chưa rõ')+'</div><div class="intelUxPrimaryFact">'+(x.priceBillion!=null?'<b>'+escIntel(moneyLabel(x.priceBillion))+'</b><small>Giá rao đọc được</small>':x.areaM2!=null?'<b>'+escIntel(areaLabel(x.areaM2))+'</b><small>Diện tích đọc được</small>':'<b>Tin rao bán</b><small>Có dữ liệu để mở kiểm tra</small>')+'</div>'+(facts.length?'<div class="intelUxFacts">'+facts.join('')+'</div>':'')+(summary?'<p class="intelUxSummary">'+escIntel(summary)+'</p>':'')+'<div class="intelUxSeen"><span>App thấy: '+escIntel(dateLabel(x.lastSeenAt||x.firstSeenAt))+'</span><span>'+escIntel(x.status==='observed'?'Vừa thấy trong luồng nguồn':'Chưa thấy lại trong luồng gần nhất')+'</span></div><div class="intelUxActions"><button type="button" class="intelUxButton save" data-intel-save="'+index+'">'+(saved?uxIcon('bookmark')+' Đã lưu':uxIcon('bookmark')+' Lưu')+'</button><button type="button" class="intelUxButton" data-intel-detail="'+index+'">'+uxIcon('detail')+' Chi tiết</button><button type="button" class="intelUxButton primary" data-intel-open="'+index+'">Mở tin gốc '+uxIcon('external')+'</button></div></article>';
  }
